import org.mockito.Mockito
import org.mockito.Mockito._
import org.scalatest.{Matchers, WordSpec}

class FooSpec extends WordSpec with Matchers {

  trait TraitWithConcreteMethods {
    def getTrue: Boolean = true
  }

  private val mockTraitWithConcreteMethods = Mockito.mock(classOf[TraitWithConcreteMethods], CALLS_REAL_METHODS)

  "mockTraitWithConcreteMethods.getTrue" should {
    "return true" in {
        val result = mockTraitWithConcreteMethods.getTrue
        result shouldBe true
      }
  }
}

//ouput
//false was not equal to true

